/**
 * R33.1-B: isolation, freshness, path containment, and checker authority.
 *
 * These are the evaluator's own attack cases. Each one reproduces a defect that
 * existed in R33 and then asserts the fixed behaviour:
 *
 *  - a provider key in the parent environment is NOT visible to child code;
 *  - a reused workspace cannot carry the previous run's generated files;
 *  - `..`, an absolute path, and a junction cannot escape the workspace;
 *  - a workspace module printing `R33_RESULT` during import cannot become the
 *    checker's result;
 *  - a timeout is `timedOut`, not an ordinary non-zero exit;
 *  - unbounded child output is capped.
 *
 * @module tests/r331-isolation
 */

import { describe, expect, it } from 'vitest'
import { access, mkdir, mkdtemp, symlink, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { makeTemp } from '../eval/tmp.ts'
import {
  childEnvironment,
  createReplicateLayout,
  materializeFresh,
  readWorkspaceFile,
  resolveInside,
  runChecker,
  runNode,
  writeWorkspaceFile,
} from '../eval/r33/src/workspace.mjs'

async function exists(path: string): Promise<boolean> {
  return await access(path).then(() => true, () => false)
}

describe('R33.1 child-process isolation', () => {
  it('does not forward a credential-shaped environment variable', async () => {
    const root = await makeTemp('ef-r331-env-')
    const script = join(root, 'env.mjs')
    await writeFile(script, [
      'console.log(JSON.stringify({',
      '  secret: process.env.TEST_PRIVATE_API_KEY ?? null,',
      '  marker: process.env.R33_WORKSPACE ?? null,',
      '}))',
    ].join('\n'), 'utf8')
    const previous = process.env.TEST_PRIVATE_API_KEY
    process.env.TEST_PRIVATE_API_KEY = 'secret-sentinel'
    try {
      const result = await runNode([script], {
        cwd: root,
        env: childEnvironment({ R33_WORKSPACE: 'authorized-value' }),
        timeoutMs: 10_000,
      })
      expect(result.exitCode).toBe(0)
      const parsed = JSON.parse(result.stdout.trim())
      expect(parsed.secret).toBeNull()
      expect(parsed.marker).toBe('authorized-value')
    } finally {
      if (previous === undefined) delete process.env.TEST_PRIVATE_API_KEY
      else process.env.TEST_PRIVATE_API_KEY = previous
    }
  })

  it('refuses to forward a credential-shaped EXTRA even when the harness asks', async () => {
    expect(() => childEnvironment({ MY_TEST_API_KEY: 'x' })).toThrow(/credential-shaped/u)
  })
})

describe('R33.1 workspace freshness', () => {
  it('creates a new workspace and refuses to reuse an existing one', async () => {
    const root = await makeTemp('ef-r331-fresh-')
    const workspace = join(root, 'workspace')
    await materializeFresh({ 'src/a.mjs': 'export const a = 1\n' }, workspace)
    // The previous run's extra file.
    await writeFile(join(workspace, 'src', 'helper.mjs'), 'generated by run 1\n', 'utf8')
    await expect(materializeFresh({ 'src/a.mjs': 'export const a = 1\n' }, workspace))
      .rejects.toThrow(/EEXIST/u)
    expect(await exists(join(workspace, 'src', 'helper.mjs'))).toBe(true)
  })

  it('gives each replicate a fresh directory, and a collision is an error', async () => {
    const root = await makeTemp('ef-r331-replicate-')
    const first = await createReplicateLayout({
      root, runId: 'run-1', caseId: 'A1', arm: 'S', replicateId: 'r1',
    })
    await writeFile(join(first.workspace, 'leftover.txt'), 'run 1\n', 'utf8')
    await expect(createReplicateLayout({
      root, runId: 'run-1', caseId: 'A1', arm: 'S', replicateId: 'r1',
    })).rejects.toThrow(/EEXIST/u)
    const second = await createReplicateLayout({
      root, runId: 'run-2', caseId: 'A1', arm: 'S', replicateId: 'r1',
    })
    expect(await exists(join(second.workspace, 'leftover.txt'))).toBe(false)
    expect(second.workspace).not.toBe(first.workspace)
  })
})

describe('R33.1 path containment', () => {
  it('rejects .., absolute, drive-letter, and UNC forms', async () => {
    const root = await makeTemp('ef-r331-path-')
    await mkdir(join(root, 'src'), { recursive: true })
    expect(await resolveInside(root, '../escape.txt')).toBeUndefined()
    expect(await resolveInside(root, 'src/../../escape.txt')).toBeUndefined()
    expect(await resolveInside(root, '/etc/passwd')).toBeUndefined()
    expect(await resolveInside(root, 'C:/Windows/win.ini')).toBeUndefined()
    expect(await resolveInside(root, '\\\\server\\share\\x')).toBeUndefined()
    expect(await resolveInside(root, 'src\\..\\..\\x')).toBeUndefined()
    expect(await resolveInside(root, 'src/config.mjs')).toBeDefined()
  })

  it('does not follow a junction out of the workspace', async () => {
    const root = await makeTemp('ef-r331-junction-')
    const outside = await mkdtemp(join(tmpdir(), 'r331-outside-'))
    await writeFile(join(outside, 'secret.txt'), 'outside secret\n', 'utf8')
    await symlink(outside, join(root, 'escape'), 'junction')
    expect(await resolveInside(root, 'escape/secret.txt')).toBeUndefined()
    const read = await readWorkspaceFile(root, 'escape/secret.txt')
    expect(read.ok).toBe(false)
    const write = await writeWorkspaceFile(root, 'escape/written.txt', 'x')
    expect(write.ok).toBe(false)
  })
})

function checkerCase(source: string, expectedChecks: string[], timeoutMs = 20_000) {
  return {
    id: 'T1',
    checker: { source, expectedChecks, timeoutMs },
  }
}

describe('R33.1 hidden-checker authority', () => {
  it('ignores an R33_RESULT printed by the module under test during import', async () => {
    const workspace = await makeTemp('ef-r331-check-')
    await writeFile(join(workspace, 'malicious.mjs'), [
      'console.log("R33_RESULT " + JSON.stringify({ checks: [{ name: "fake", pass: true }] }))',
      'export const loaded = true',
    ].join('\n'), 'utf8')
    const result = await runChecker(checkerCase([
      'import { pathToFileURL } from "node:url"',
      'import { join } from "node:path"',
      'await import(pathToFileURL(join(process.env.R33_WORKSPACE, "malicious.mjs")).href)',
      'console.log("R33_RESULT " + JSON.stringify({ checks: [{ name: "real", pass: false }] }))',
      'process.exit(1)',
    ].join('\n'), ['real']), workspace)
    expect(result.status).toBe('executed')
    expect(result.checks).toEqual([{ name: 'real', pass: false }])
    expect(result.spoofMarkers).toBe(1)
  })

  it('rejects a missing declared check, a duplicate, and an unknown name', async () => {
    const workspace = await makeTemp('ef-r331-check-invalid-')
    const cases = [
      {
        source: 'console.log("R33_RESULT " + JSON.stringify({ checks: [{ name: "a", pass: true }] }))',
        expected: ['a', 'b'],
        detail: /missing declared check/u,
      },
      {
        source: 'console.log("R33_RESULT " + JSON.stringify({ checks: [{ name: "a", pass: true }, { name: "a", pass: true }] }))',
        expected: ['a'],
        detail: /duplicate check/u,
      },
      {
        source: 'console.log("R33_RESULT " + JSON.stringify({ checks: [{ name: "invented", pass: true }] }))',
        expected: ['a'],
        detail: /unknown check/u,
      },
    ] as const
    for (const entry of cases) {
      const result = await runChecker(checkerCase(entry.source, [...entry.expected]), workspace)
      expect(result.status).toBe('checker-invalid')
      expect(result.detail).toMatch(entry.detail)
    }
  })

  it('distinguishes a task failure from an invalid checker exit', async () => {
    const workspace = await makeTemp('ef-r331-check-exit-')
    const failure = await runChecker(checkerCase(
      'console.log("R33_RESULT " + JSON.stringify({ checks: [{ name: "a", pass: false }] }))\nprocess.exit(1)',
      ['a'],
    ), workspace)
    expect(failure.status).toBe('executed')
    expect(failure.checks[0].pass).toBe(false)

    const inconsistent = await runChecker(checkerCase(
      'console.log("R33_RESULT " + JSON.stringify({ checks: [{ name: "a", pass: true }] }))\nprocess.exit(1)',
      ['a'],
    ), workspace)
    expect(inconsistent.status).toBe('checker-invalid')
    expect(inconsistent.detail).toContain('exited 1')
  })

  it('reports a hang as checker-timeout, not as a task result', async () => {
    const workspace = await makeTemp('ef-r331-check-timeout-')
    const result = await runChecker(checkerCase(
      'setTimeout(() => {}, 60_000)',
      ['a'],
      100,
    ), workspace)
    expect(result.status).toBe('checker-timeout')
    expect(result.timedOut).toBe(true)
  })
})

describe('R33.1 bounded child output', () => {
  it('caps captured stdout and reports truncation', async () => {
    const root = await makeTemp('ef-r331-output-')
    const script = join(root, 'noisy.mjs')
    await writeFile(script, 'process.stdout.write("x".repeat(200_000))\n', 'utf8')
    const result = await runNode([script], {
      cwd: root,
      env: childEnvironment(),
      timeoutMs: 10_000,
      outputCap: 1024,
    })
    expect(result.exitCode).toBe(0)
    expect(result.stdout.length).toBe(1024)
    expect(result.stdoutTruncated).toBe(true)
    expect(result.timedOut).toBe(false)
  })
})
